INSERT IGNORE INTO `products` (`id`, `store_id`, `primary_category_id`, `name`, `slug`, `description`, `brand`, `thumbnail`, `status`, `is_active`, `created_at`, `updated_at`) VALUES
	(1, 1, 3, 'Android Flagship Premium Samsung', 'android-flagship-premium-samsung-001', 'Android Flagship Premium Samsung adalah produk demo marketplace untuk kategori Handphone & Tablet > Smartphone > Android Flagship. Produk dibuat dengan data realistis untuk kebutuhan katalog, pencarian, keranjang, wishlist, dan transaksi.', 'Samsung', 'https://cdn.kishamarket.test/products/product-001.jpg', 'published', 1, '2026-07-10 01:13:49', '2026-07-10 01:13:49'),
	(2, 2, 4, 'Android Mid Range Original Apple', 'android-mid-range-original-apple-002', 'Android Mid Range Original Apple adalah produk demo marketplace untuk kategori Handphone & Tablet > Smartphone > Android Mid Range. Produk dibuat dengan data realistis untuk kebutuhan katalog, pencarian, keranjang, wishlist, dan transaksi.', 'Apple', 'https://cdn.kishamarket.test/products/product-002.jpg', 'published', 1, '2026-07-10 01:13:49', '2026-07-10 01:13:49'),
	(3, 3, 5, 'iPhone Pro ASUS', 'iphone-pro-asus-003', 'iPhone Pro ASUS adalah produk demo marketplace untuk kategori Handphone & Tablet > Smartphone > iPhone. Produk dibuat dengan data realistis untuk kebutuhan katalog, pencarian, keranjang, wishlist, dan transaksi.', 'ASUS', 'https://cdn.kishamarket.test/products/product-003.jpg', 'published', 1, '2026-07-10 01:13:49', '2026-07-10 01:13:49'),
	(4, 4, 6, 'Tablet Android Daily Lenovo', 'tablet-android-daily-lenovo-004', 'Tablet Android Daily Lenovo adalah produk demo marketplace untuk kategori Handphone & Tablet > Smartphone > Tablet Android. Produk dibuat dengan data realistis untuk kebutuhan katalog, pencarian, keranjang, wishlist, dan transaksi.', 'Lenovo', 'https://cdn.kishamarket.test/products/product-004.jpg', 'published', 1, '2026-07-10 01:13:49', '2026-07-10 01:13:49'),
	(5, 5, 7, 'Aksesoris Handphone Compact Logitech', 'aksesoris-handphone-compact-logitech-005', 'Aksesoris Handphone Compact Logitech adalah produk demo marketplace untuk kategori Handphone & Tablet > Smartphone > Aksesoris Handphone. Produk dibuat dengan data realistis untuk kebutuhan katalog, pencarian, keranjang, wishlist, dan transaksi.', 'Logitech', 'https://cdn.kishamarket.test/products/product-005.jpg', 'published', 1, '2026-07-10 01:13:49', '2026-07-10 01:13:49'),
	(6, 6, 9, 'Smartwatch Elite Sony', 'smartwatch-elite-sony-006', 'Smartwatch Elite Sony adalah produk demo marketplace untuk kategori Handphone & Tablet > Wearable > Smartwatch. Produk dibuat dengan data realistis untuk kebutuhan katalog, pencarian, keranjang, wishlist, dan transaksi.', 'Sony', 'https://cdn.kishamarket.test/products/product-006.jpg', 'published', 1, '2026-07-10 01:13:49', '2026-07-10 01:13:49'),
	(7, 7, 10, 'Smartband Series JBL', 'smartband-series-jbl-007', 'Smartband Series JBL adalah produk demo marketplace untuk kategori Handphone & Tablet > Wearable > Smartband. Produk dibuat dengan data realistis untuk kebutuhan katalog, pencarian, keranjang, wishlist, dan transaksi.', 'JBL', 'https://cdn.kishamarket.test/products/product-007.jpg', 'published', 1, '2026-07-10 01:13:49', '2026-07-10 01:13:49'),
